{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Private therapy offerings: short intensives and focused pathways for adults in {{CITY}}, {{STATE}}. Confidential clinical care and clear session boundaries.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <ul>
          <li><a href="/about.html">Practice</a></li>
          <li><a href="/services.html">Services</a></li>
          <li><a href="/approach.html">Approach</a></li>
          <li><a href="/fees.html">Investment</a></li>
          <li><a href="/faq.html">Q&amp;A</a></li>
          <li><a href="/book.html" class="cta small">{{PRIMARY_CTA_LABEL}}</a></li>
          <li><a href="/contact.html">Reach Out</a></li>
        </ul>
      </nav>
      <button class="mobile-toggle" aria-expanded="false" aria-controls="nav">Menu</button>
    </div>
  </header>

  <main>
    <!-- HERO / Poster -->
    <section class="hero poster-hero" aria-labelledby="hero-heading">
      <div class="pattern-bg" aria-hidden="true"></div>
      <div class="wrap hero-inner">
        <div class="hero-text">
          <h1 id="hero-heading">A focused intensive path for the moment you need clarity</h1>
          <p class="lead">Short clinical intensives and time-limited pathways to explore a particular knot — practical, private, and clinically grounded.</p>
          <p class="meta">Sessions offered in-office and telehealth for adults in {{CITY}}, {{STATE}}.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/services.html">View pathways</a>
          </div>
        </div>

        <aside class="hero-proof" aria-label="Proof gallery">
          <div class="testimonial-rotator" id="hero-rotator">
            <blockquote class="quote">"I left with a clearer sense of next steps — and practical language I could use right away."</blockquote>
            <cite>— Client, short-term intensive</cite>
          </div>
          <ul class="small-badges" aria-hidden="false" id="hero-badges">
            <li class="badge" data-title="Licensed clinician — state board">
              <svg viewBox="0 0 24 24" class="badge-ico" aria-hidden="true"><circle cx="12" cy="12" r="10"/></svg>
              <span class="sr-only">Credential</span>
            </li>
            <li class="badge" data-title="20+ years clinical experience">
              <svg viewBox="0 0 24 24" class="badge-ico" aria-hidden="true"><rect x="4" y="4" width="16" height="16"/></svg>
            </li>
            <li class="badge" data-title="Private practice — small caseload">
              <svg viewBox="0 0 24 24" class="badge-ico" aria-hidden="true"><path d="M3 12h18"/></svg>
            </li>
          </ul>
        </aside>
      </div>
    </section>

    <!-- Myth vs Truth -->
    <section class="myth-truth wrap">
      <h2>Myths we often hear</h2>
      <div class="grid">
        <div class="card">
          <h3>Myth</h3>
          <p>Therapy is only for crises.</p>
        </div>
        <div class="card">
          <h3>Truth</h3>
          <p>Short, focused work can bring vocabulary and steps to use between sessions — useful before a crisis arrives.</p>
        </div>
        <div class="card">
          <h3>Myth</h3>
          <p>Progress must be linear.</p>
        </div>
        <div class="card">
          <h3>Truth</h3>
          <p>Clinical work is a series of adjustments; we plan small experiments that respect your pace.</p>
        </div>
      </div>
    </section>

    <!-- Pillars -->
    <section class="pillars wrap" id="pillars">
      <h2>Core features of the intensive pathway</h2>
      <ul class="pillars-list">
        <li>
          <h4>Focused intake + plan</h4>
          <p>One session for assessment and a concise, written plan with clear goals.</p>
        </li>
        <li>
          <h4>Time-bound sessions</h4>
          <p>Short series (4–8 sessions) aimed at a discrete concern — navigation, transition, or decision-making.</p>
        </li>
        <li>
          <h4>Tools and language</h4>
          <p>Practical strategies and phrasing to use outside sessions so progress is tangible.</p>
        </li>
      </ul>
    </section>

    <!-- Proof Gallery (full) -->
    <section class="proof-gallery wrap" aria-labelledby="proof-heading">
      <h2 id="proof-heading">Proof Gallery</h2>
      <p class="intro">Rotating client reflections and a compact display of professional credibility.</p>

      <div class="gallery">
        <div class="carousel" id="testimonials">
          <button class="prev" aria-label="Previous testimonial">‹</button>
          <div class="slides" id="slides" role="list">
            <figure role="listitem">
              <blockquote>"Concrete steps that felt possible — I was surprised how quickly the work paid off."</blockquote>
              <figcaption>— Adult client, 6-week pathway</figcaption>
            </figure>
            <figure role="listitem">
              <blockquote>"Clear boundaries and confidentiality made it easier to bring hard topics into the room."</blockquote>
              <figcaption>— Client, single-session intake</figcaption>
            </figure>
            <figure role="listitem">
              <blockquote>"The plan wasn't prescriptive; it was a set of experiments I could try between sessions."</blockquote>
              <figcaption>— Client, focused series</figcaption>
            </figure>
          </div>
          <button class="next" aria-label="Next testimonial">›</button>
        </div>

        <aside class="credibility" aria-hidden="false" id="cred">
          <ul class="cred-list">
            <li class="cred-item" data-tip="Licensed — state mental health board"><svg viewBox="0 0 24 24"><path d="M12 2 L20 6 L12 22 L4 6 Z"/></svg><span>State License</span></li>
            <li class="cred-item" data-tip="Clinical supervision and continuing education"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/></svg><span>Ongoing CE</span></li>
            <li class="cred-item" data-tip="Small practice — focused availability"><svg viewBox="0 0 24 24"><rect x="5" y="5" width="14" height="14"/></svg><span>Private Practice</span></li>
          </ul>
          <div class="tooltip" id="badge-tooltip" role="status" aria-live="polite"></div>
        </aside>
      </div>
    </section>

    <!-- Case Notes (therapy tone) -->
    <section class="case-notes wrap">
      <h2>How I work — session boundaries and confidentiality</h2>
      <p class="muted">Below are standard professional practices. If you have questions about how these apply to you, we can review them during intake.</p>

      <div class="accordion" id="boundaries">
        <button class="acc-toggle" aria-expanded="false" aria-controls="panel-1">Session length, cancellations, and fees</button>
        <div class="acc-panel" id="panel-1" hidden>
          <p>Standard sessions are 50 minutes unless otherwise agreed. Cancellation policy: please notify within 48 hours so we can offer the time to another client; fees for late cancellations are discussed at intake.</p>
        </div>

        <button class="acc-toggle" aria-expanded="false" aria-controls="panel-2">Confidentiality and limits</button>
        <div class="acc-panel" id="panel-2" hidden>
          <p>Clinical notes and communications are kept private, with exceptions required by law (immediate risk of harm to self or others, or certain legal processes). I will discuss confidentiality and its limits before you share sensitive information.</p>
        </div>

        <button class="acc-toggle" aria-expanded="false" aria-controls="panel-3">Telehealth and recordkeeping</button>
        <div class="acc-panel" id="panel-3" hidden>
          <p>Telehealth sessions are conducted with secure platforms when possible; notes are retained according to professional standards. We will review how records are stored during intake.</p>
        </div>
      </div>

      <div class="crisis-note" role="note">
        <p>If you are in immediate danger or a medical emergency, call local emergency services right away. If you are in crisis and need urgent support but are not in immediate danger, consider your local crisis line or 988 (U.S.). This practice does not provide emergency services.</p>
      </div>
    </section>

    <!-- FAQ small -->
    <section class="faq wrap" id="faq">
      <h2>Questions people bring</h2>
      <dl>
        <dt>Do you accept insurance?</dt>
        <dd>Insurance policies vary. I provide superbills where appropriate; we can discuss specifics during contact.</dd>
        <dt>How long is an intensive?</dt>
        <dd>Intensives are typically a single focused intake plus 3–7 follow-up sessions depending on goals.</dd>
        <dt>What are the topics you work with?</dt>
        <dd>Transitions, decision-making, anxiety about change, relationship navigation, and aligning values with action. If your concern falls outside usual scope, I will help you find appropriate care.</dd>
      </dl>
    </section>

    <!-- CTA -->
    <section class="cta wrap" aria-labelledby="cta-heading">
      <h2 id="cta-heading">Ready to begin a focused pathway?</h2>
      <p>Schedule an intake to clarify goals and design a short, practical plan.</p>
      <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <p class="small">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
    </section>

  </main>

  <footer class="site-footer wrap">
    <div class="foot-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">Private practice. Licensure and scope discussed at intake.</p>
      </div>
      <div>
        <nav aria-label="Footer">
          <ul>
            <li><a href="/about.html">Practice</a></li>
            <li><a href="/services.html">Services</a></li>
            <li><a href="/contact.html">Contact</a></li>
          </ul>
        </nav>
      </div>
      <div>
        <p class="muted">Confidentiality and scope: Clinical care does not replace emergency services. For crisis, call local emergency services or 988 (U.S.).</p>
      </div>
    </div>
    <p class="meta small">&copy; <span id="year"></span> {{BUSINESS_NAME}} — <span class="sr-only">Located in</span>{{CITY}}, {{STATE}}</p>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
