{"path":"assets/css/styles.css","content":"/* Core reset */
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.4;color:#132233;margin:0;background:#f7fafc}
.wrap{max-width:1000px;margin:0 auto;padding:28px}
.site-header{background:#fff;border-bottom:1px solid #e6eef5}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:#0b2a36;text-decoration:none}
.main-nav ul{list-style:none;margin:0;padding:0;display:flex;gap:14px;align-items:center}
.main-nav a{color:#0b2a36;text-decoration:none;padding:8px}
.cta.small{background:#0b6677;color:#fff;padding:8px 12px;border-radius:6px}
.mobile-toggle{display:none}

/* Hero */
.poster-hero{position:relative;overflow:hidden;padding:56px 0}
.pattern-bg{position:absolute;inset:0;background-image:url('/assets/img/pattern.svg');background-size:cover;opacity:0.06}
.hero-inner{display:grid;grid-template-columns:1fr 320px;gap:24px;align-items:start}
.hero-text{background:linear-gradient(180deg,rgba(255,255,255,0.9),rgba(255,255,255,0.6));padding:28px;border-radius:10px}
.lead{font-size:1.05rem;color:#234047}
.meta{color:#5b6d72;font-size:0.9rem}
.hero-actions{margin-top:16px}
.btn{display:inline-block;text-decoration:none;padding:10px 16px;border-radius:8px}
.btn.primary{background:#0b6677;color:#fff}
.btn.ghost{background:transparent;border:1px solid #cfe6ea;color:#0b6677}
.btn.large{padding:14px 20px}

.hero-proof{background:#fff;padding:18px;border-radius:10px;border:1px solid #e6eef5}
.testimonial-rotator{min-height:80px}
.quote{font-style:italic;margin:0 0 8px 0}
.small-badges{display:flex;gap:10px;margin-top:12px;padding:0;list-style:none}
.badge{width:36px;height:36px;border-radius:6px;background:#e9f3f4;display:flex;align-items:center;justify-content:center;position:relative;cursor:default}
.badge-ico{width:18px;height:18px;fill:#0b6677}

/* Myth vs Truth */
.myth-truth{padding:30px;background:#fff;margin-top:18px;border-radius:10px}
.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
.card{background:#fbfeff;padding:14px;border-radius:8px;border:1px solid #e0f0f2}
.card h3{margin:0 0 8px 0}

/* Pillars */
.pillars{margin-top:18px}
.pillars-list{display:flex;gap:14px;list-style:none;padding:0}
.pillars-list li{flex:1;background:#fff;padding:16px;border-radius:8px;border:1px solid #e8f3f5}

/* Proof gallery */
.proof-gallery{margin-top:18px;padding:18px;background:#fff;border-radius:10px;border:1px solid #e6eef5}
.gallery{display:flex;gap:16px;align-items:flex-start}
.carousel{flex:1;display:flex;align-items:center;gap:8px}
.slides{overflow:hidden;position:relative;width:100%;height:120px}
.slides figure{position:absolute;left:0;top:0;width:100%;margin:0;padding:12px}
.prev,.next{background:#0b6677;color:#fff;border:none;padding:8px;border-radius:6px;cursor:pointer}
.credibility{width:220px}
.cred-list{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:10px}
.cred-item{display:flex;gap:8px;align-items:center;background:#f8feff;padding:8px;border-radius:8px;border:1px solid #e1f3f4;cursor:pointer;position:relative}
.cred-item svg{width:28px;height:28px;fill:#0b6677}
.tooltip{position:relative;padding:8px;margin-top:12px;color:#fff;background:#0b6677;border-radius:6px;min-height:36px;display:none}

/* Accordion */
.accordion{margin-top:18px}
.acc-toggle{display:block;width:100%;text-align:left;padding:12px;background:#fff;border:1px solid #e6eef5;border-radius:8px;margin-top:8px;cursor:pointer}
.acc-panel{padding:12px;border-left:3px solid #0b6677;background:#fbffff;border-radius:0 8px 8px 8px}
.crisis-note{margin-top:12px;padding:12px;background:#fff3f3;border-left:4px solid #d9534f;border-radius:8px}

/* FAQ */
.faq{margin-top:18px;background:#fff;padding:18px;border-radius:10px;border:1px solid #e6eef5}
.faq dl{display:grid;gap:8px}
.faq dt{font-weight:700}
.faq dd{margin:0;color:#476167}

/* Footer */
.site-footer{margin-top:28px;padding:18px 0;border-top:1px solid #e6eef5;background:#fff}
.foot-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}
.small{font-size:0.9rem}
.muted{color:#64767b}
.meta{color:#5b6d72}
.sr-only{position:absolute!important;height:1px;width:1px;overflow:hidden;clip:rect(1px,1px,1px,1px);white-space:nowrap}

/* Responsive */
@media(max-width:840px){
  .hero-inner{grid-template-columns:1fr;}
  .main-nav{display:none}
  .mobile-toggle{display:block}
  .foot-grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Utilities
  function $(sel, ctx){return (ctx||document).querySelector(sel)}
  function $all(sel, ctx){return Array.from((ctx||document).querySelectorAll(sel))}

  // Year
  document.getElementById('year').textContent = new Date().getFullYear();

  // Mobile nav toggle
  var mobileToggle = $('.mobile-toggle');
  var nav = $('.main-nav');
  mobileToggle && mobileToggle.addEventListener('click', function(){
    var expanded = this.getAttribute('aria-expanded') === 'true';
    this.setAttribute('aria-expanded', !expanded);
    if(nav) nav.style.display = expanded ? 'none' : 'block';
  });

  // Hero rotator (small)
  var heroRotator = $('#hero-rotator');
  if(heroRotator){
    var heroTexts = [
      '"I left with a clearer sense of next steps — and practical language I could use right away."',
      '"A small number of focused sessions helped me decide with less anxiety."',
      '"We planned short experiments that felt achievable between meetings."'
    ];
    var hIndex = 0;
    setInterval(function(){
      hIndex = (hIndex+1) % heroTexts.length;
      var q = heroRotator.querySelector('.quote');
      if(q) q.textContent = heroTexts[hIndex];
    },4000);
  }

  // Testimonial carousel (full)
  var slidesWrap = $('#slides');
  var prev = $('.prev');
  var next = $('.next');
  if(slidesWrap){
    var slides = Array.from(slidesWrap.querySelectorAll('figure'));
    slides.forEach(function(s,i){s.style.transform = 'translateX(' + (i*100) + '%)'});
    var idx = 0;
    function show(i){
      slides.forEach(function(s,j){s.style.transform = 'translateX(' + ((j-i)*100) + '%)';});
    }
    prev && prev.addEventListener('click', function(){ idx = (idx-1+slides.length)%slides.length; show(idx); });
    next && next.addEventListener('click', function(){ idx = (idx+1)%slides.length; show(idx); });
    // Auto-rotate
    setInterval(function(){ idx = (idx+1)%slides.length; show(idx); },6000);
  }

  // Credibility badge tooltips
  var credItems = $all('.cred-item');
  var tooltip = $('#badge-tooltip');
  credItems.forEach(function(item){
    item.addEventListener('mouseenter', function(){
      var tip = item.getAttribute('data-tip') || '';
      tooltip.textContent = tip;
      tooltip.style.display = 'block';
    });
    item.addEventListener('mouseleave', function(){
      tooltip.style.display = 'none';
      tooltip.textContent = '';
    });
    // Keyboard accessibility
    item.addEventListener('focus', function(){
      var tip = item.getAttribute('data-tip') || '';
      tooltip.textContent = tip; tooltip.style.display='block';
    });
    item.addEventListener('blur', function(){ tooltip.style.display='none'; tooltip.textContent=''; });
  });

  // Small badges tooltip in hero
  $all('.small-badges .badge').forEach(function(b){
    var title = b.getAttribute('data-title');
    if(!title) return;
    b.addEventListener('mouseenter', function(){
      var t = document.createElement('div');
      t.className = 'hero-badge-tip';
      t.textContent = title;
      t.style.position='absolute';t.style.top='42px';t.style.left='0';t.style.background='#0b6677';t.style.color='#fff';t.style.padding='6px 8px';t.style.borderRadius='6px';t.style.fontSize='12px';
      b.appendChild(t);
    });
    b.addEventListener('mouseleave', function(){
      var tip = b.querySelector('.hero-badge-tip'); if(tip) tip.remove();
    });
  });

  // Accordion behavior
  $all('.acc-toggle').forEach(function(btn){
    btn.addEventListener('click', function(){
      var expanded = this.getAttribute('aria-expanded') === 'true';
      this.setAttribute('aria-expanded', !expanded);
      var panel = document.getElementById(this.getAttribute('aria-controls'));
      if(panel){
        if(expanded){ panel.hidden = true; } else { panel.hidden = false; }
      }
    });
  });

  // Respectful focus outlines for keyboard users
  function handleFirstTab(e){
    if(e.key === 'Tab'){
      document.documentElement.classList.add('user-is-tabbing');
      window.removeEventListener('keydown', handleFirstTab);
    }
  }
  window.addEventListener('keydown', handleFirstTab);

})();"} 
